<?php require_once __DIR__.'/../auth.php';require_admin();$id=(int)($_GET['id']??0);$b=['title'=>'','author'=>'','category'=>'Fiction','price'=>'','description'=>''];$error='';if($id){$s=$conn->prepare('SELECT * FROM books WHERE id=?');$s->bind_param('i',$id);$s->execute();$found=$s->get_result()->fetch_assoc();if(!$found)exit('Book not found');$b=$found;}if($_SERVER['REQUEST_METHOD']==='POST'){$b['title']=trim($_POST['title']??'');$b['author']=trim($_POST['author']??'');$b['category']=trim($_POST['category']??'');$b['price']=$_POST['price']??'';$b['description']=trim($_POST['description']??'');if(!$b['title']||!$b['author']||!$b['category']||!is_numeric($b['price'])||(float)$b['price']<0)$error='Complete required fields and enter a valid price.';else{$price=(float)$b['price'];if($id){$s=$conn->prepare('UPDATE books SET title=?,author=?,category=?,price=?,description=? WHERE id=?');$s->bind_param('sssdsi',$b['title'],$b['author'],$b['category'],$price,$b['description'],$id);}else{$s=$conn->prepare('INSERT INTO books(title,author,category,price,description) VALUES(?,?,?,?,?)');$s->bind_param('sssds',$b['title'],$b['author'],$b['category'],$price,$b['description']);}if($s->execute()){header('Location: books.php');exit;}$error='Could not save record.';}}$page_title=$id?'Edit Book':'Add Book';$root_prefix='../';$asset_prefix='../';include __DIR__.'/../header.php';?><div class="form wide"><h1><?= $id?'Edit':'Add' ?> book</h1><?php if($error): ?><p class="error"><?= htmlspecialchars($error) ?></p><?php endif; ?><form method="post"><label>Title *<input name="title" required value="<?= htmlspecialchars($b['title']) ?>"></label><label>Author *<input name="author" required value="<?= htmlspecialchars($b['author']) ?>"></label><label>Category *<input name="category" required value="<?= htmlspecialchars($b['category']) ?>"></label><label>Price *<input type="number" min="0" step=".01" name="price" required value="<?= htmlspecialchars((string)$b['price']) ?>"></label><label>Description<textarea name="description" rows="4"><?= htmlspecialchars($b['description']) ?></textarea></label><button>Save book</button> <a href="books.php">Cancel</a></form></div><?php include __DIR__.'/../footer.php'; ?>